-- ====================================================================
-- 02_seed_katalog.sql
-- Seed 80 Produk dari Dataset Coffee Shop Sales (Maven Roasters)
-- Asumsi Kurs: 1 USD = Rp16,000 (Pembulatan Rp500)
-- ====================================================================

ON DUPLICATE KEY UPDATE 
    `nama`=VALUES(`nama`),
    `kategori`=VALUES(`kategori`),
    `kategori_dataset`=VALUES(`kategori_dataset`),
    `tipe_dataset`=VALUES(`tipe_dataset`),
    `ukuran`=VALUES(`ukuran`),
    `harga`=VALUES(`harga`),
    `harga_dolar_ref`=VALUES(`harga_dolar_ref`),
    `gambar`=IF(`gambar` LIKE 'catalog-%', VALUES(`gambar`), `gambar`),
    `aktif`=1;

UPDATE `products` SET `aktif`=0 WHERE `id_produk` NOT IN ('PRDM0001', 'PRDM0002', 'PRDM0003', 'PRDM0004', 'PRDM0005', 'PRDM0006', 'PRDM0007', 'PRDM0008', 'PRDM0009', 'PRDM0010', 'PRDM0011', 'PRDM0012', 'PRDM0013', 'PRDM0014', 'PRDM0015', 'PRDM0016', 'PRDM0017', 'PRDM0018', 'PRDM0019', 'PRDM0020', 'PRDM0021', 'PRDM0022', 'PRDM0023', 'PRDM0024', 'PRDM0025', 'PRDM0026', 'PRDM0027', 'PRDM0028', 'PRDM0029', 'PRDM0030', 'PRDM0031', 'PRDM0032', 'PRDM0033', 'PRDM0034', 'PRDM0035', 'PRDM0036', 'PRDM0037', 'PRDM0038', 'PRDM0039', 'PRDM0040', 'PRDM0041', 'PRDM0042', 'PRDM0043', 'PRDM0044', 'PRDM0045', 'PRDM0046', 'PRDM0047', 'PRDM0048', 'PRDM0049', 'PRDM0050', 'PRDM0051', 'PRDM0052', 'PRDM0053', 'PRDM0054', 'PRDM0055', 'PRDM0056', 'PRDM0057', 'PRDM0058', 'PRDM0059', 'PRDM0060', 'PRDM0061', 'PRDM0063', 'PRDM0064', 'PRDM0065', 'PRDM0069', 'PRDM0070', 'PRDM0071', 'PRDM0072', 'PRDM0073', 'PRDM0074', 'PRDM0075', 'PRDM0076', 'PRDM0077', 'PRDM0078', 'PRDM0079', 'PRDM0081', 'PRDM0082', 'PRDM0083', 'PRDM0084', 'PRDM0087');
